const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry Definition: Northern Siberia east of the Taz River
  // Approximate bounding box for northern Siberia (adjust as needed)
  const northSiberia = ee.Geometry.Polygon(
    [[[60.0, 75.0], [60.0, 65.0], [180.0, 65.0], [180.0, 75.0]]], null, false
  );

  // Taz River is located around 78-80° E longitude.
  // We'll define "east of the Taz River" as east of approximately 80° E.
  const tazRiverLongitude = 80;
  const geometry = ee.Geometry.Rectangle({
    coords: [tazRiverLongitude, 65.0, 180.0, 75.0], // East of 80E, within northern Siberia latitude range
    geodesic: false // Use Cartesian for simplicity over this large area
  }).intersection(northSiberia); // Ensure it's still within the broader Northern Siberia box

  // Define scale for reducing regions (in meters). Using a larger scale to avoid memory errors
  // given the large area and the complexity of connected components.
  // A scale of 1000m means 1 pixel represents 1km^2.
  const scale = 1000;

  // 2. Data Acquisition and Processing Functions
  const getLandsatCollection = (year, bandNames, region) => {
    let collection;
    if (year <= 1993) { // Landsat 4/5 for 1973
      collection = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
        .filterDate(`${year}-06-01`, `${year}-09-30`) // Summer months for lake visibility
        .filterBounds(region);
    } else if (year >= 1999 && year <= 2003) { // Landsat 7 for 2002
      collection = ee.ImageCollection('LANDSAT/LE07/C01/T1_SR')
        .filterDate(`${year}-06-01`, `${year}-09-30`)
        .filterBounds(region);
    } else {
      return ee.ImageCollection([]); // No suitable collection
    }

    // Cloud masking for Landsat SR collections
    const cloudMask = (image) => {
      const qa = image.select('pixel_qa');
      // Bits 3 and 5 are cloud and cloud shadow respectively.
      const cloud = qa.bitwiseAnd(1 << 3).neq(0)
        .or(qa.bitwiseAnd(1 << 5).neq(0));
      // Bit 7 is snow/ice, also mask it out
      const snow = qa.bitwiseAnd(1 << 4).neq(0);
      return image.updateMask(cloud.not().and(snow.not()))
        .select(bandNames)
        .multiply(0.0000275).add(-0.2) // Scale surface reflectance
        .copyProperties(image, ['system:time_start']);
    };

    return collection.map(cloudMask);
  };

  const calculateMNDWI = (image, year) => {
    let greenBand, swir1Band;
    if (year <= 1993) { // Landsat 4/5
      greenBand = 'B2'; // Green
      swir1Band = 'B5'; // SWIR1
    } else { // Landsat 7
      greenBand = 'B2'; // Green
      swir1Band = 'B5'; // SWIR1
    }
    return image.normalizedDifference([greenBand, swir1Band]).rename('MNDWI');
  };

  const countLakes = async (collection, year, region, description) => {
    const bandNames = (year <= 1993) ? ['B2', 'B5', 'pixel_qa'] : ['B2', 'B5', 'pixel_qa'];

    const filteredCollection = getLandsatCollection(year, bandNames, region);
    const collectionSize = await filteredCollection.size().getInfo();
    console.log(`${description} images found: ${collectionSize}`);

    if (collectionSize === 0) {
      console.log(`No images for ${description}.`);
      return { lakeCount: null, validPixels: 0 };
    }

    // Select the least cloudy image, or mosaic if multiple clear images are needed
    const image = filteredCollection.qualityMosaic('MNDWI');
    if (!image) { // If qualityMosaic returns null due to empty collection
        console.log(`Failed to create mosaic for ${description}.`);
        return { lakeCount: null, validPixels: 0 };
    }

    // Calculate MNDWI
    const mndwi = calculateMNDWI(image, year);

    // Threshold MNDWI to identify water. A threshold of 0 is common.
    const waterMask = mndwi.gt(0).selfMask();

    // Count valid water pixels
    const waterPixelCount = await waterMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e12,
      tileScale: 16 // Increase tileScale for large regions
    }).get('MNDWI').getInfo();

    if (waterPixelCount === 0 || waterPixelCount === null) {
      console.log(`No valid water pixels after masking for ${description}.`);
      return { lakeCount: 0, validPixels: waterPixelCount || 0 };
    }

    // Use connectedComponents to label individual water bodies
    const connectedComponents = waterMask.connectedComponents({
      connectedness: 8, // 8-way connectivity
      maxSize: 1024 // Filter out very small components (noise)
    }).select('labels');

    // Count distinct labels (lakes)
    const distinctLakes = await connectedComponents.reduceRegion({
      reducer: ee.Reducer.countDistinct(),
      geometry: region,
      scale: scale,
      maxPixels: 1e12,
      tileScale: 16
    }).get('labels').getInfo();

    // The reducer returns the number of unique values, which is the count of components + 1 (for the "no data" value 0 if present).
    // So, we subtract 1 if 0 is a valid label, but connectedComponents starts labeling from 1.
    // However, if there are no components, it might return null or 0.
    const finalLakeCount = distinctLakes ? distinctLakes : 0; // If null, means 0 lakes.

    console.log(`${description} Valid Water Pixels: ${waterPixelCount}`);
    console.log(`${description} Estimated Lake Count: ${finalLakeCount}`);

    return { lakeCount: finalLakeCount, validPixels: waterPixelCount };
  };

  try {
    // 3. Perform Calculations
    const result1973 = await countLakes(null, 1973, geometry, '1973');
    const result2002 = await countLakes(null, 2002, geometry, '2002');

    const lakes1973 = result1973.lakeCount;
    const lakes2002 = result2002.lakeCount;

    // 4. Validation and Final Answer
    if (lakes1973 === null || lakes2002 === null) {
      if (result1973.validPixels === 0 || result2002.validPixels === 0) {
        console.log("No valid pixels remain after processing for one or both years.");
        console.log("C2");
      } else {
        console.log("Calculation failed (null result for lake count).");
        console.log("C3");
      }
      return;
    }

    if (lakes1973 === 0 && lakes2002 === 0) {
      console.log("No lakes found in either year.");
      console.log("B"); // If no lakes exist, it didn't decrease.
      return;
    }

    if (lakes2002 < lakes1973) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.error("An error occurred:", error);
    console.log("D"); // General error
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

